import {
  component$,
  useStore,
  useVisibleTask$,
  type PropFunction,
} from "@builder.io/qwik";
import type { Persona } from "../../types";
import { loadPersonasFromIdb } from "../../utils/idb";
import { PERSONAS as DEFAULT_PERSONAS } from "../../utils/personas";
import type { SelectionActionState } from "./editor-state";

interface SelectionActionsProps {
  selection: SelectionActionState | null;
  disabled?: boolean;
  onGetSources$: PropFunction<() => void>;
  onAddMargin$: PropFunction<() => void>;
  onSendToPersona$: PropFunction<
    (personaId: string, personaName: string) => void
  >;
  onClose$: PropFunction<() => void>;
}

interface SelectionActionsStore {
  personas: Persona[];
  personaOpen: boolean;
}

/** A compact, manuscript-anchored action card for a selected passage. */
export const SelectionActions = component$<SelectionActionsProps>((props) => {
  const store = useStore<SelectionActionsStore>({
    personas: DEFAULT_PERSONAS,
    personaOpen: false,
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const custom = await loadPersonasFromIdb();
    if (custom?.length) store.personas = custom;
  });

  const selection = props.selection;
  if (!selection) return null;

  return (
    <div
      class={["selection-actions", `selection-actions--${selection.placement}`]}
      style={{ left: `${selection.x}px`, top: `${selection.y}px` }}
      role="toolbar"
      aria-label={`Actions for “${selection.text.slice(0, 70)}”`}
      onMouseDown$={(event) => {
        // Keep the Tiptap selection intact while a card control receives focus.
        if (!(event.target instanceof HTMLTextAreaElement))
          event.preventDefault();
      }}
    >
      <div class="selection-actions__quote" title={selection.text}>
        “{selection.text.slice(0, 82)}
        {selection.text.length > 82 ? "…" : ""}”
      </div>
      <div class="selection-actions__row">
        <button
          type="button"
          onClick$={props.onGetSources$}
          disabled={props.disabled}
        >
          Get sources
        </button>
        <button
          type="button"
          onClick$={props.onAddMargin$}
          disabled={props.disabled}
        >
          Add margin
        </button>
        <button
          type="button"
          aria-haspopup="menu"
          aria-expanded={store.personaOpen}
          onClick$={() => {
            store.personaOpen = !store.personaOpen;
          }}
          disabled={props.disabled}
        >
          Send to persona
        </button>
        <button
          type="button"
          class="selection-actions__close"
          onClick$={props.onClose$}
          aria-label="Dismiss selection actions"
        >
          ×
        </button>
      </div>
      {selection.error && (
        <p class="selection-actions__error" role="status">
          {selection.error}
        </p>
      )}
      {store.personaOpen && (
        <div class="selection-actions__personas" role="menu">
          <p>Request a reading from</p>
          {store.personas.map((persona) => (
            <button
              key={persona.id}
              type="button"
              role="menuitem"
              onClick$={() => {
                store.personaOpen = false;
                props.onSendToPersona$(persona.id, persona.name);
              }}
            >
              <span
                class="selection-actions__persona-mark"
                style={{ color: persona.color }}
                aria-hidden="true"
              >
                {persona.icon}
              </span>
              <span>
                <strong>{persona.name}</strong>
                <small>{persona.role}</small>
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
});
import { component$, type PropFunction } from "@builder.io/qwik";
import { renderMarkdown } from "../../utils/markdown";
import { SpeakButton } from "../ui/speak-button";
import type { UserCommentPopover } from "./editor-state";

interface UserCommentPanelProps {
  comment: UserCommentPopover | null;
  onClose$: PropFunction<() => void>;
  onDraftChange$: PropFunction<(draft: string) => void>;
  onCreate$: PropFunction<() => void>;
  onDiscard$: PropFunction<() => void>;
  onSubmit$: PropFunction<(commentId: string) => void>;
  onToggleResolved$: PropFunction<(commentId: string) => void>;
  onDelete$: PropFunction<(commentId: string) => void>;
}

/** The writer's conversation around one inline comment mark. */
export const UserCommentPanel = component$<UserCommentPanelProps>((props) => {
  const comment = props.comment;
  const onDraftChange$ = props.onDraftChange$;
  const onCreate$ = props.onCreate$;
  const onDiscard$ = props.onDiscard$;
  const onSubmit$ = props.onSubmit$;
  const onToggleResolved$ = props.onToggleResolved$;
  const onDelete$ = props.onDelete$;

  if (!comment || !comment.visible) return null;

  const composing = comment.mode === "compose";

  return (
    <div
      class="manuscript-comment-card manuscript-comment-card--writer"
      style={{
        left: `${comment.x}px`,
        top: comment.top != null ? `${comment.top}px` : "auto",
        bottom: comment.bottom != null ? `${comment.bottom}px` : "auto",
        "max-height": `${comment.maxH}px`,
        "--comment-color": "var(--color-writer-note)",
      }}
      role="dialog"
      aria-label={
        composing ? "Write a margin note" : `Note from ${comment.author}`
      }
      onClick$={(event) => event.stopPropagation()}
    >
      <div class="manuscript-comment-card__head">
        <div class="min-w-0">
          <p class="manuscript-comment-card__author">You</p>
          <p
            class="manuscript-comment-card__label"
            style={{
              color: comment.resolved
                ? "var(--color-accent-green)"
                : "var(--color-writer-note)",
            }}
          >
            {composing
              ? "New margin"
              : `${comment.resolved ? "resolved" : "open"} · ${timeAgo(comment.createdAt)}`}
          </p>
        </div>
        <div class="flex items-center gap-1.5 flex-shrink-0">
          {!composing && (
            <SpeakButton
              compact
              id={`user-comment-${comment.id}`}
              text={comment.text}
            />
          )}
          <button
            onClick$={props.onClose$}
            class="manuscript-comment-card__close"
            aria-label="Close margin note"
          >
            ✕
          </button>
        </div>
      </div>

      <div class="manuscript-comment-card__body">
        {comment.quote && (
          <blockquote class="manuscript-comment-card__quote">
            {`« ${comment.quote.length > 280 ? comment.quote.slice(0, 279) + "…" : comment.quote} »`}
          </blockquote>
        )}

        {composing ? (
          <div class="manuscript-comment-card__composer">
            <textarea
              autoFocus
              value={comment.draft}
              onInput$={(_, element) => onDraftChange$(element.value)}
              onKeyDown$={(event) => {
                if (
                  (event.metaKey || event.ctrlKey) &&
                  event.key === "Enter" &&
                  comment.draft.trim()
                ) {
                  event.preventDefault();
                  onCreate$();
                }
                if (event.key === "Escape") onDiscard$();
              }}
              placeholder="What belongs in the margin here?"
              class="manuscript-comment-card__textarea"
              rows={5}
            />
            <div class="manuscript-comment-card__actions">
              <span>⌘↩ to place</span>
              <div class="flex gap-2">
                <button onClick$={onDiscard$} class="btn-paper text-[11px]">
                  Discard
                </button>
                <button
                  onClick$={onCreate$}
                  disabled={!comment.draft.trim()}
                  class="btn-press text-[11px] disabled:opacity-30 disabled:cursor-not-allowed"
                >
                  Place note
                </button>
              </div>
            </div>
          </div>
        ) : (
          <>
            <div
              data-speech-id={`user-comment-${comment.id}`}
              class="comment-markdown text-[0.95rem] leading-6 text-[var(--color-ink)]"
              style="font-family: var(--font-serif);"
              dangerouslySetInnerHTML={renderMarkdown(comment.text)}
            />

            {comment.replies.length > 0 && (
              <div
                class="pt-2 mt-2 border-t border-dashed space-y-2"
                style={{ "border-color": "var(--color-paper-3)" }}
              >
                {comment.replies.map((reply) => (
                  <div key={reply.id} class="text-[0.85rem]">
                    <p
                      class="text-[0.6rem] tracking-[0.16em] uppercase"
                      style={{
                        fontFamily: "var(--font-typewriter)",
                        color:
                          reply.authorKind === "persona" && reply.color
                            ? reply.color
                            : "var(--color-ink-muted)",
                      }}
                    >
                      {reply.author}
                      {reply.authorKind === "persona" && (
                        <span class="ml-1.5 opacity-70">editor</span>
                      )}{" "}
                      · {timeAgo(reply.createdAt)}
                    </p>
                    <div
                      class="comment-markdown mt-0.5 text-[var(--color-ink-light)] leading-5"
                      style={{
                        fontFamily: "var(--font-serif)",
                        fontStyle:
                          reply.authorKind === "persona" ? "italic" : "normal",
                      }}
                      dangerouslySetInnerHTML={renderMarkdown(reply.text)}
                    />
                  </div>
                ))}
              </div>
            )}

            <div class="manuscript-comment-card__composer">
              <textarea
                value={comment.draft}
                onInput$={(_, element) => onDraftChange$(element.value)}
                onKeyDown$={(event) => {
                  if (
                    (event.metaKey || event.ctrlKey) &&
                    event.key === "Enter"
                  ) {
                    onSubmit$(comment.id);
                  }
                }}
                placeholder="Reply as the writer…"
                class="manuscript-comment-card__textarea"
                rows={3}
              />
              <div class="manuscript-comment-card__actions">
                <span>⌘↩ to reply</span>
                <div class="flex gap-2">
                  <button
                    onClick$={() => onToggleResolved$(comment.id)}
                    class="btn-paper text-[11px]"
                  >
                    {comment.resolved ? "Reopen" : "Resolve"}
                  </button>
                  <button
                    onClick$={() => onDelete$(comment.id)}
                    class="btn-paper text-[11px] text-[var(--color-vermilion)]"
                  >
                    Erase
                  </button>
                  <button
                    onClick$={() => onSubmit$(comment.id)}
                    disabled={!comment.draft.trim()}
                    class="btn-press text-[11px] disabled:opacity-30 disabled:cursor-not-allowed"
                  >
                    Reply
                  </button>
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
});

function timeAgo(timestamp: number): string {
  const seconds = Math.floor((Date.now() - timestamp) / 1000);
  if (seconds < 60) return "just now";
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}
import { Mark, type Editor } from "@tiptap/core";

export interface CommentMarkOptions {
  HTMLAttributes: Record<string, any>;
}

export interface CommentMarkAttributes {
  id: string;
  author?: string;
  color?: string;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    commentMark: {
      setComment: (attrs: CommentMarkAttributes) => ReturnType;
      unsetComment: () => ReturnType;
    };
  }
}

export const CommentMark = Mark.create<CommentMarkOptions>({
  name: "commentMark",

  // Margin threads are independent even when they quote the same passage.
  // Allow multiple comment marks to coexist instead of letting the newest one
  // replace the first at an identical selection.
  excludes: "",

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addAttributes() {
    return {
      id: {
        default: null,
        parseHTML: (element) => element.getAttribute("data-comment-id"),
        renderHTML: (attributes) => {
          if (!attributes.id) return {};
          return { "data-comment-id": attributes.id };
        },
      },
      author: {
        default: "You",
        parseHTML: (element) => element.getAttribute("data-comment-author"),
        renderHTML: (attributes) => {
          if (!attributes.author) return {};
          return { "data-comment-author": attributes.author };
        },
      },
      color: {
        default: "var(--color-writer-note)",
        parseHTML: (element) => {
          const color = element.getAttribute("data-comment-color");
          // Migrate comments saved before writer notes received their own
          // semantic color. Mustard belongs to M. Le Stylo.
          return !color || color === "var(--color-mustard)"
            ? "var(--color-writer-note)"
            : color;
        },
        renderHTML: (attributes) => {
          if (!attributes.color) return {};
          return { "data-comment-color": attributes.color };
        },
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: "span[data-comment-id]",
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    const color =
      HTMLAttributes["data-comment-color"] ?? "var(--color-writer-note)";
    return [
      "span",
      {
        ...this.options.HTMLAttributes,
        ...HTMLAttributes,
        class: "twyne-comment-mark",
        style: `background: color-mix(in srgb, ${color} 18%, transparent); border-bottom: 2px solid ${color}; cursor: text;`,
      },
      0,
    ];
  },

  addCommands() {
    return {
      setComment:
        (attrs) =>
        ({ chain }) => {
          return chain()
            .setMark("commentMark", {
              id: attrs.id,
              author: attrs.author ?? "You",
              color: attrs.color ?? "var(--color-writer-note)",
            })
            .run();
        },
      unsetComment:
        () =>
        ({ chain }) => {
          return chain().unsetMark("commentMark").run();
        },
    };
  },
});

/** Remove one comment id without disturbing another mark on the same quote. */
export function removeCommentMarkById(
  editor: Editor,
  commentId: string,
): boolean {
  const { state, view } = editor;
  const type = state.schema.marks.commentMark;
  if (!type) return false;

  const tr = state.tr;
  state.doc.descendants((node, pos) => {
    if (!node.isText) return true;
    for (const mark of node.marks) {
      if (mark.type === type && mark.attrs.id === commentId) {
        tr.removeMark(pos, pos + node.nodeSize, mark);
      }
    }
    return true;
  });
  if (!tr.docChanged) return false;
  view.dispatch(tr);
  return true;
}

