      if (!chain) return;
      if (size) chain.setFontSize(size).run();
      else chain.unsetFontSize().run();
    });

    const applyLineHeight = $((value: string | null) => {
      const chain = store.editor?.chain().focus();
      if (!chain) return;
      chain.setParagraphLineHeight(value).run();
    });

    const applySpaceBefore = $((points: number | null) => {
      store.editor?.chain().focus().setSpaceBefore(points).run();
    });

    const applySpaceAfter = $((points: number | null) => {
      store.editor?.chain().focus().setSpaceAfter(points).run();
    });

    const applyKeepWithNext = $((enabled: boolean) => {
      store.editor?.chain().focus().setKeepWithNext(enabled).run();
    });

    /**
     * Recase the selection in place.
     *
     * Only text nodes are replaced, in reverse document order. That preserves
     * the marks on each node (bold, links, comments, suggestions) instead of
     * flattening the selected range into unformatted text.
     */
    const applyTextCase = $((mode: TextCase) => {
      const editor = store.editor;
      if (!editor) return;
      const { from, to } = editor.state.selection;
      if (from === to) return;
      const segments: Array<{
        from: number;
        to: number;
        text: string;
        marks: readonly any[];
      }> = [];
      editor.state.doc.nodesBetween(from, to, (node, pos) => {
        if (!node.isText || !node.text) return;
        const segmentFrom = Math.max(from, pos);
        const segmentTo = Math.min(to, pos + node.nodeSize);
        if (segmentFrom >= segmentTo) return;
        const start = segmentFrom - pos;
        const end = segmentTo - pos;
        segments.push({
          from: segmentFrom,
          to: segmentTo,
          text: node.text.slice(start, end),
          marks: node.marks,
        });
      });
      const edits = recaseTextSegments(segments, mode);
      let tr = editor.state.tr;
      for (let i = edits.length - 1; i >= 0; i--) {
        const edit = edits[i];
        if (edit.text === segments[i].text) continue;
        tr = tr.replaceWith(
          edit.from,
          edit.to,
          editor.state.schema.text(edit.text, segments[i].marks),
        );
      }
      if (!tr.docChanged) return;
      tr.setSelection(
        TextSelection.create(tr.doc, from, Math.min(to, tr.doc.content.size)),
      );
      editor.view.dispatch(tr);
      editor.commands.focus();
    });

    const runCommand = $(async (command: string) => {
      const chain = store.editor?.chain().focus();
      if (!chain) return;
      switch (command) {
        case "bold":
          chain.toggleBold().run();
          break;
        case "italic":
          chain.toggleItalic().run();
          break;
        case "underline":
          chain.toggleUnderline().run();
          break;
        case "strike":
          chain.toggleStrike().run();
          break;
        case "highlight":
          chain.toggleHighlight().run();
          break;
        case "superscript":
          // Mutually exclusive with subscript: text cannot be raised and
          // lowered at once, and TipTap will happily apply both.
          chain.unsetSubscript().toggleSuperscript().run();
          break;
        case "subscript":
          chain.unsetSuperscript().toggleSubscript().run();
          break;
        case "justify":
          chain.setTextAlign("justify").run();
          break;
        case "clearFormatting":
          // Marks and block type both — "clear formatting" that left a
          // heading a heading would not match anyone's expectation.
          chain.unsetAllMarks().unsetParagraphFormat().clearNodes().run();
          break;
        case "h1":
          chain.toggleHeading({ level: 1 }).run();
          break;
        case "h2":
          chain.toggleHeading({ level: 2 }).run();
          break;
        case "h3":
          chain.toggleHeading({ level: 3 }).run();
          break;
        case "bullet":
          chain.toggleBulletList().run();
          break;
        case "ordered":
          chain.toggleOrderedList().run();
          break;
        case "taskList":
          chain.toggleTaskList().run();
          break;
        case "blockquote":
          chain.toggleBlockquote().run();
          break;
        case "code":
          chain.toggleCodeBlock().run();
          break;
        case "left":
          chain.setTextAlign("left").run();
          break;
        case "center":
          chain.setTextAlign("center").run();
          break;
        case "right":
          chain.setTextAlign("right").run();
          break;
        case "horizontal":
          chain.setHorizontalRule().run();
          break;
        case "pageBreak":
          chain.setPageBreak().run();
          break;
        case "undo":
          chain.undo().run();
          break;
        case "redo":
          chain.redo().run();
          break;
        case "insertTable":
          chain.insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run();
          break;
        case "addRowBefore":
          chain.addRowBefore().run();
          break;
        case "addRowAfter":
          chain.addRowAfter().run();
          break;
        case "deleteRow":
          chain.deleteRow().run();
          break;
        case "addColumnBefore":
          chain.addColumnBefore().run();
          break;
        case "addColumnAfter":
          chain.addColumnAfter().run();
          break;
        case "deleteColumn":
          chain.deleteColumn().run();
          break;
        case "toggleHeaderRow":
          chain.toggleHeaderRow().run();
          break;
        case "toggleHeaderColumn":
          chain.toggleHeaderColumn().run();
          break;
        case "mergeCells":
          chain.mergeCells().run();
          break;
        case "splitCell":
          chain.splitCell().run();
          break;
        case "deleteTable":
          chain.deleteTable().run();
          break;
        case "addComment": {
          const editor = store.editor!;
          const { from, to } = editor.state.selection;
          if (from === to) break;
          await openWriterMarginComposer({ from, to });
          break;
        }
        case "insertNote": {
          const noteText = store.noteText.trim();
          if (noteText) {
            if (store.noteInputKind === "footnote") {
              chain.setFootnote({ text: noteText }).run();
            } else {
              chain.setEndnote({ text: noteText }).run();
            }
            store.editor?.chain().insertContent(" ").run();
          }
          store.noteText = "";
          store.noteInputKind = null;
          break;
        }

        case "insertMermaid": {
          if (store.mermaidSource.trim()) {
            chain
              .setMermaidDiagram({ source: store.mermaidSource.trim() })
              .run();
            store.mermaidSource = "";
            store.showMermaidInput = false;
          }
          break;
        }
      }
    });

    const handleTableToolbarIntent = $((intent: TableToolbarIntent) => {
      const editor = store.editor;
      if (!editor) return;
      runTableToolbarIntent(editor, intent, store.tableToolbar.anchor?.width);
    });

    const handleCellFormatIntent = $((intent: TableCellFormatIntent) => {
      const editor = store.editor;
      if (!editor) return;
      runTableCellFormatIntent(editor, intent);
    });

    const insertTableDimensions = $(
      (rows: number, columns: number, withHeaderRow: boolean) => {
        store.editor
          ?.chain()
          .focus()
          .insertTable({ rows, cols: columns, withHeaderRow })
          .run();
        store.showTableInsertion = false;
      },
    );

    const runRegistryCommand = $(async (commandId: EditorCommandId) => {
      const alias = REGISTRY_COMMAND_ALIASES[commandId];
      if (alias) {
        await runCommand(alias);
        return;
      }

      const editor = store.editor;
      switch (commandId) {
        case "insert.image":
          store.showImageInput = true;
          break;
        case "insert.table":
          store.showTableInsertion = true;
          break;
        case "insert.mermaid":
          store.showMermaidInput = true;
          break;
        case "insert.math-inline":
          editor?.chain().focus().setInlineMath({ source: "" }).run();
          break;
        case "insert.math-block":
          editor?.chain().focus().setBlockMath({ source: "" }).run();
          break;
        case "insert.endnote":
          store.noteInputKind = "endnote";
          store.noteText = "";
          break;
        case "insert.footnote":
          store.noteInputKind = "footnote";
          store.noteText = "";
          break;
        case "review.comment":
          await runCommand("addComment");
          break;
        case "review.read-aloud":
          await readAloud();
          break;
        case "navigate.find":
        case "navigate.replace":
          store.showFindReplace = true;
          break;
        case "navigate.outline":
          store.showOutline = true;
          break;
        case "view.shortcuts":
          store.showShortcutDialog = true;
          break;
        case "view.zen":
          store.zenMode = !store.zenMode;
          window.dispatchEvent(
            new CustomEvent("twyne:zen-mode", {
              detail: { on: store.zenMode },
            }),
          );
          break;
        default:
          break;
      }
    });

    const selectSlashCommand = $(async (commandId: EditorCommandId) => {
      const editor = store.editor;
      if (!editor) return;
      editor.commands.removeSlashCommandQuery();
      await runRegistryCommand(commandId);
      editor.commands.focus();
      store.slashOpen = false;
    });

    const getSourcesForSelection = $(async () => {
      const selection = store.selectionAction;
      if (!selection) return;
      await onEditorialContext$?.("citations");
      const result = await researchSelection({
        anchor: selection.text,
        folioId: store.activeFolioId,
      });
      const current = store.selectionAction;
      if (
        !result.ok &&
        current?.from === selection.from &&
        current.to === selection.to
      ) {
        store.selectionAction = {
          ...current,
          error: result.message ?? "The Apparatus could not start.",
        };
      }
    });

    const addMarginForSelection = $(async () => {
      const selection = store.selectionAction;
      if (!selection || !store.editor) return;
      store.editor.commands.setTextSelection({
        from: selection.from,
        to: selection.to,
      });
      await openWriterMarginComposer({
        from: selection.from,
        to: selection.to,
      });
    });

    const sendSelectionToPersona = $(
      async (personaId: string, personaName: string) => {
        const selection = store.selectionAction;
        if (!selection) return;
        const commentId = await createSelectionComment(
          `Please give me ${personaName}'s editorial reading of this passage.`,
          { from: selection.from, to: selection.to },
          false,
        );
        if (!commentId) {
          const current = store.selectionAction;
          if (current) {
            store.selectionAction = {
              ...current,
              error: "The margin request could not be filed.",
            };
          }
          return;
        }
        store.selectionAction = null;
        await onEditorialContext$?.("comments");
        window.dispatchEvent(
          new CustomEvent("twyne:ask-persona-on-comment", {
            detail: { commentId, personaId },
          }),
        );
      },
    );

    return (
      <div class="flex flex-1 flex-col min-h-0">
        {readOnly && (
          <div
            class="border-b border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] px-4 py-2 text-xs text-[var(--color-ink-light)]"
            role="status"
          >
            Commenter access. You can read and discuss this folio, but only its
            owner and editors can change the manuscript.
          </div>
        )}
        {/* Sticky chrome stack: toolbar plus whichever inline input bar is
            active (image, note, comment, mermaid). All live in one sticky
            wrapper so the active bar always sits flush under the toolbar
            rather than scrolling out of view as the manuscript scrolls. */}
        <div class="sticky top-0" style={{ zIndex: "var(--z-sticky)" }}>
          <CompositorPanel
            store={store}
            onCommand$={runCommand}
            onHighlight$={applyHighlight}
            onTextColor$={applyTextColor}
            onFontFamily$={applyFontFamily}
            onFontSize$={applyFontSize}
            onLineHeight$={applyLineHeight}
            onSpaceBefore$={applySpaceBefore}
            onSpaceAfter$={applySpaceAfter}
            onKeepWithNext$={applyKeepWithNext}
            onTextCase$={applyTextCase}
            onReadAloud$={readAloud}
            onLayoutChange$={emitLayout}
            onChromeTextChange$={updateChromeText}
            onSavePdf$={saveAsPdf}
          />
          {store.showFindReplace && (
            <div
              class="fixed right-4 top-16"
              style={{ zIndex: "var(--z-dropdown)" }}
            >
              <FindReplacePanel
                editor={store.editor ? noSerialize(store.editor) : null}
                onClose$={() => {
                  store.showFindReplace = false;
                }}
              />
            </div>
          )}

          {store.showGrammar && (
            <GrammarPanel
              editor={store.editor ? noSerialize(store.editor) : null}
          onLayoutChange$={emitLayout}
          onHeaderCommit$={(value) => updateChromeText("header", value)}
          onFooterCommit$={(value) => updateChromeText("footer", value)}
          onJumpToNote$={jumpToNote}
        />

        <SelectionActions
          selection={
            store.userCommentPopover?.visible ? null : store.selectionAction
          }
          onGetSources$={getSourcesForSelection}
          onAddMargin$={addMarginForSelection}
          onSendToPersona$={sendSelectionToPersona}
          onClose$={() => {
            store.selectionAction = null;
          }}
        />

        <PersonaNotePanel
          note={store.notePopover}
          onPin$={(noteId) => {
            const note = store.notePopover;
            if (note?.id === noteId && !note.pinned) {
              store.notePopover = { ...note, pinned: true };
            }
          }}
          onClose$={() => {
            store.notePopover = null;
          }}
          onDraftChange$={(draft) => {
            const note = store.notePopover;
            if (note) store.notePopover = { ...note, draft };
          }}
          onReply$={(noteId, text, author) => {
            window.dispatchEvent(
              new CustomEvent("twyne:persona-reply", {
                detail: { noteId, text, author },
              }),
            );
            const note = store.notePopover;
            if (note?.id === noteId) {
              store.notePopover = { ...note, draft: "", error: null };
            }
          }}
          onStrike$={(noteId) => {
            dismissNote(noteId);
            if (store.notePopover?.id === noteId) {
              store.notePopover = null;
            }
          }}
        />
        <SuggestionPanel
          suggestion={store.suggestionPopover}
          stampVisible={store.stampVisible}
          onClose$={() => {
            store.suggestionPopover = null;
          }}
          onStrike$={strikeSuggestion}
          onAccept$={acceptSuggestion}
        />

        <UserCommentPanel
          comment={store.userCommentPopover}
          onClose$={closeUserCommentPopover}
          onDraftChange$={(draft) => {
            if (!store.userCommentPopover) return;
            store.userCommentPopover = {
              ...store.userCommentPopover,
              draft,
            };
          }}
          onCreate$={submitWriterMargin}
          onDiscard$={discardWriterMargin}
          onSubmit$={submitUserCommentReply}
          onToggleResolved$={toggleResolveUserComment}
          onDelete$={deleteUserCommentLocal}
        />
      </div>
    );
  },
);

/* ── Persona note helpers ─────────────────────────────────────── */

/**
 * Locate `quote` inside a single text block of the document and return its
/**
 * Writer-authored inline comments — local persistence. The CommentMark
 * in the manuscript holds the id; the body, replies, and resolve state
 * live in Lix at `/user-comments.json`. The same shape gets pushed to
 * Convex via `convex-sync.ts:pushLocalSnapshot`, so the cross-device
 * sync is automatic.
 *
 * The shape is deliberately flat — comments and replies are denormalised
 * so the editor can render without a join.
 *
 * This is the single source of truth for "the room's comments on the
 * manuscript" — the inline CommentMark popover and the right-rail
 * Marginalia panel both read and write here. The legacy `/comments.json`
 * shape is migrated on first load.
 */

import { readFileAsJson, writeFileAsJson } from "./lix";

export type UserCommentAuthor = "user" | "persona";

export interface UserCommentReply {
  id: string;
  author: string;
  /** user = the writer; persona = an editor answering the thread. */
  authorKind: UserCommentAuthor;
  /** Set when authorKind === "persona". */
  personaId?: string;
  /** Color swatch to render the reply in (mirrors the persona's accent). */
  color?: string;
  text: string;
  createdAt: number;
}

export interface UserComment {
  id: string;
  folioId: string;
  text: string;
  author: string;
  /** The passage the comment was pinned to (for scroll-to + display). */
  anchor?: string;
  resolved: boolean;
  createdAt: number;
  updatedAt: number;
  replies: UserCommentReply[];
  /**
   * Key into the local `voice-notes` IndexedDB store when this note was
   * spoken. The comment's `text` is the transcript; this is the recording it
   * came from, which carries the hesitation and emphasis the transcript
   * drops. Local-only by design — audio does not sync.
   */
  audioId?: string;
  audioDurationMs?: number;
  /** Which provider produced the transcript, for the provider tag. */
  transcriptProvider?: string;
}

const COMMENTS_PATH = "/user-comments.json";
const LEGACY_COMMENTS_PATH = "/comments.json";

export async function loadUserComments(): Promise<UserComment[]> {
  if (typeof window === "undefined") return [];
  try {
    const data = await readFileAsJson<UserComment[]>(COMMENTS_PATH);
    if (data && data.length > 0) return data;
  } catch {
    // fall through to migration
  }
  // One-time migration from the legacy `/comments.json` panel model into
  // the unified UserComment store. New comments are anchored by selection;
  // legacy ones had no anchor, so we keep `selectedText` as the anchor.
  try {
    const legacy = await readFileAsJson<LegacyComment[]>(LEGACY_COMMENTS_PATH);
    if (Array.isArray(legacy) && legacy.length > 0) {
      const migrated: UserComment[] = legacy.map((c) => ({
        id: c.id,
        folioId: "", // legacy comments had no folio scope
        text: c.text,
        author: c.author,
        anchor: c.selectedText || undefined,
        resolved: c.resolved,
        createdAt: c.timestamp,
        updatedAt: c.timestamp,
        replies: (c.replies ?? []).map((r) => ({
          id: r.id,
          author: r.author,
          authorKind: "user",
          text: r.text,
          createdAt: r.timestamp,
        })),
      }));
      await writeFileAsJson(COMMENTS_PATH, migrated);
      // Wipe the legacy path so we don't re-migrate next time.
      try {
        await writeFileAsJson(LEGACY_COMMENTS_PATH, []);
      } catch {
        // best-effort
      }
      return migrated;
    }
  } catch {
    // no legacy file
  }
  return [];
}

export async function saveUserComments(comments: UserComment[]): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    await writeFileAsJson(COMMENTS_PATH, comments);
  } catch {
    // lix unavailable
  }
}

/**
 * Drop every writer-authored thread from the Lix store. Used
 * by "File a new piece" — without this, the threads would
 * orphan against the (now empty) folios and turn into ghost
 * notes the next time the writer opens the editor. Returns
 * the number of threads cleared so the caller can show a
 * confirmation.
 */
export async function clearUserComments(): Promise<number> {
  if (typeof window === "undefined") return 0;
  let count = 0;
  try {
    const all = await loadUserComments();
    count = all.length;
    await writeFileAsJson(COMMENTS_PATH, []);
  } catch {
    // best-effort
  }
  return count;
}

export async function upsertUserComment(
  c: UserComment,
): Promise<UserComment[]> {
  const all = await loadUserComments();
  const idx = all.findIndex((x) => x.id === c.id);
  if (idx >= 0) {
    // Merge: keep any replies that landed before the parent body
    // (e.g. a reply sent in the same race window where the popover
    // opened before persistNewComment finished). The caller controls
    // the body, anchor, folioId, and resolve state; the reply thread
    // is owned by appendUserCommentReply, so we never clobber it.
    all[idx] = {
      ...all[idx],
      ...c,
      replies: c.replies.length > 0 ? c.replies : all[idx].replies,
    };
  } else {
    all.push(c);
  }
  await saveUserComments(all);
  return all;
}

export async function appendUserCommentReply(
  commentId: string,
  reply: UserCommentReply,
): Promise<UserComment[]> {
  const all = await loadUserComments();
  const idx = all.findIndex((x) => x.id === commentId);
  const now = Date.now();
  if (idx < 0) {
    // The parent comment hasn't been persisted yet — usually because the
    // editor opened the popover the same instant it set the mark, and the
    // upsert and the reply are racing. Rather than silently drop the
    // writer's reply, file a placeholder parent that owns the reply. The
    // subsequent upsert will merge into it (same id, body filled in).
    all.push({
      id: commentId,
      folioId: "",
      text: "",
      author: reply.authorKind === "persona" ? reply.author : "You",
      resolved: false,
      createdAt: reply.createdAt,
      updatedAt: now,
      replies: [reply],
    });
    await saveUserComments(all);
    return all;
  }
  all[idx] = {
    ...all[idx],
    replies: [...all[idx].replies, reply],
    updatedAt: now,
  };
  await saveUserComments(all);
  return all;
}

export async function toggleUserCommentResolved(
  commentId: string,
): Promise<UserComment[]> {
  const all = await loadUserComments();
  const idx = all.findIndex((x) => x.id === commentId);
  if (idx < 0) return all;
  all[idx] = {
    ...all[idx],
    resolved: !all[idx].resolved,
    updatedAt: Date.now(),
  };
  await saveUserComments(all);
  return all;
}

export async function deleteUserComment(
  commentId: string,
): Promise<UserComment[]> {
  const all = await loadUserComments();
  const next = all.filter((x) => x.id !== commentId);
  await saveUserComments(next);
  return next;
}

