    editor.view.dom.addEventListener(
      "touchstart",
      dismissEditorialFurniture,
      true,
    );
    cleanup(() => {
      editor.view.dom.removeEventListener(
        "mousedown",
        dismissEditorialFurniture,
        true,
      );
      editor.view.dom.removeEventListener(
        "touchstart",
        dismissEditorialFurniture,
        true,
      );
    });

    // Sharing must serialize the exact document Tiptap owns, including
    // edits still inside the route's persistence debounce. The share
    // control requests this snapshot synchronously immediately before it
    // mirrors and serializes Lix.
    const provideDraftSnapshot = (event: Event) => {
      const detail = (event as CustomEvent<DraftSnapshotRequest>).detail;
      if (detail.folioId === store.activeFolioId) {
        detail.html = editor.getHTML();
      }
    };
    window.addEventListener(DRAFT_SNAPSHOT_REQUEST, provideDraftSnapshot);
    cleanup(() =>
      window.removeEventListener(
        DRAFT_SNAPSHOT_REQUEST,
        provideDraftSnapshot,
      ),
    );

    const refreshActive = () => {
      const { from, to } = editor.state.selection;
      store.hasSelection = from !== to;
      if (from !== to && editor.state.selection instanceof TextSelection) {
        const text = editor.state.doc.textBetween(from, to, " ").trim();
        if (text) {
          const start = editor.view.coordsAtPos(from);
          const end = editor.view.coordsAtPos(to);
          const cardHalfWidth = Math.min(240, window.innerWidth / 2 - 8);
          const center =
            (Math.min(start.left, end.left) +
              Math.max(start.right, end.right)) /
            2;
          const x = Math.max(
            cardHalfWidth,
            Math.min(window.innerWidth - cardHalfWidth, center),
          );
          const placement = start.top > 112 ? "above" : "below";
          const prior = store.selectionAction;
          store.selectionAction = {
            from,
            to,
            text,
            x,
            y: placement === "above" ? start.top - 10 : end.bottom + 10,
            placement,
            error:
              prior?.from === from && prior.to === to ? prior.error : null,
          };
        } else {
          store.selectionAction = null;
        }
      } else {
        store.selectionAction = null;
      }
      store.active = {
        bold: editor.isActive("bold"),
        italic: editor.isActive("italic"),
        underline: editor.isActive("underline"),
        strike: editor.isActive("strike"),
        highlight: editor.isActive("highlight"),
        h1: editor.isActive("heading", { level: 1 }),
        h2: editor.isActive("heading", { level: 2 }),
        h3: editor.isActive("heading", { level: 3 }),
        bullet: editor.isActive("bulletList"),
        ordered: editor.isActive("orderedList"),
        taskList: editor.isActive("taskList"),
        blockquote: editor.isActive("blockquote"),
        code: editor.isActive("codeBlock"),
        left: editor.isActive({ textAlign: "left" }),
        center: editor.isActive({ textAlign: "center" }),
        right: editor.isActive({ textAlign: "right" }),
        justify: editor.isActive({ textAlign: "justify" }),
        superscript: editor.isActive("superscript"),
        subscript: editor.isActive("subscript"),
        isInTable: editor.isActive("table"),
        canMergeCells: editor.can().mergeCells(),
        canSplitCell: editor.can().splitCell(),
      };
      store.selectedImage = editor.isActive("image")
        ? (editor.getAttributes("image") as ImageNodeAttributes)
        color:
          suggestionSpan.getAttribute("data-suggestion-color") ??
          "var(--color-vermilion)",
        original: suggestionSpan.textContent ?? "",
        replacement:
          suggestionSpan.getAttribute("data-suggestion-replacement") ?? "",
        rationale:
          suggestionSpan.getAttribute("data-suggestion-rationale") ?? "",
        x: Math.max(8, Math.min(rect.left, window.innerWidth - 360)),
        y: rect.bottom + 8,
        busy: false,
      };
    };

    // ── Hover: preview a persona note below its sentence ──
    // Non-blocking rules:
    //   1. Hover-intent delay (350ms) — passing through doesn't
    //      accidentally open a card.
    //   2. Typing disarm — once the writer types (or deletes /
    //      hits Enter), the next hover is suppressed. We re-arm
    //      only on real mouse motion (>3px), filtering the
    //      synthetic mousemove that scroll-under-cursor fires.
    //   3. Pinned / replying / has-thread cards never close from
    //      mouseout alone.
    let hoverTimer: ReturnType<typeof setTimeout> | null = null;
    let hoverArmed = true;
    let hoveredWriterCommentId: string | null = null;
    let lastMouse = { x: 0, y: 0 };
    const clearHoverTimer = () => {
      if (hoverTimer) {
        clearTimeout(hoverTimer);
        hoverTimer = null;
      }
    };
    el.addEventListener("mouseover", (e) => {
      const target = e.target as HTMLElement;
      const noteSpan = target.closest(
        ".twyne-persona-note",
      ) as HTMLElement | null;
      const writerCommentSpan = target.closest(
        ".twyne-comment-mark",
      ) as HTMLElement | null;
      const chip = target.closest(
        ".twyne-mark-anchor",
      ) as HTMLElement | null;
      if (!noteSpan && !writerCommentSpan && !chip) return;
      if (writerCommentSpan) {
        if (store.userCommentPopover?.visible) return;
        if (!hoverArmed) return;
        const commentId =
          writerCommentSpan.getAttribute("data-comment-id") ?? "";
        if (!commentId) return;
        clearHoverTimer();
        hoverTimer = setTimeout(() => {
          hoveredWriterCommentId = commentId;
          void openUserCommentPopover(commentId, writerCommentSpan);
        }, 350);
        return;
      }
      // Don't clobber a pinned card the writer is interacting with.
      if (store.notePopover?.pinned) return;
      if (!hoverArmed) return;
      // Resolve to the actual note span for geometry. The chip
      // belongs to whichever note span it sits in (or directly
      // adjacent to).
      const anchor =
        noteSpan ??
        (chip?.closest(".twyne-persona-note") as HTMLElement | null);
      if (!anchor) return;
      clearHoverTimer();
      hoverTimer = setTimeout(() => {
        buildAndPin(anchor, false);
      }, 350);
    });
    el.addEventListener("mouseout", (e) => {
      const related = (e as MouseEvent).relatedTarget as HTMLElement | null;
      // Stay open while moving onto the card, the marked span, or
      // its corresponding anchor chip (text → chip → card).
      if (related?.closest(".manuscript-comment-card")) return;
      if (related?.closest(".twyne-persona-note")) return;
      if (related?.closest(".twyne-comment-mark")) return;
      if (related?.closest(".twyne-mark-anchor")) return;
      // Even when we don't close, cancel any pending hover-open
      // timer so a fast pass-through doesn't surprise the writer.
      clearHoverTimer();
      if (hoveredWriterCommentId) {
        if (
          store.userCommentPopover?.id === hoveredWriterCommentId &&
          !store.userCommentPopover.draft.trim()
        ) {
          store.userCommentPopover = null;
        }
        hoveredWriterCommentId = null;
        return;
      }
      // Mid-conversation: keep the live thread open even if the
      // popover was opened by hover rather than a click.
      if (store.notePopover?.pinned) return;
      if (store.notePopover?.replying) return;
      if ((store.notePopover?.thread.length ?? 0) > 0) return;
      store.notePopover = null;
    });

    // ── Click handler: anchor-chip routes by data-anchor-kind; mark
    // clicks fall through to ProseMirror (caret placement, no popover). ──
    el.addEventListener("click", (e) => {
      dismissEditorialFurniture();
      const target = e.target as HTMLElement;

      // Anchor chip first — must preventDefault so clicking the
      // chip doesn't also place the caret.
      const chip = target.closest(
        ".twyne-mark-anchor",
      ) as HTMLElement | null;
      if (chip) {
        e.preventDefault();
        const kind = chip.getAttribute("data-anchor-kind");
        const id = chip.getAttribute("data-anchor-id") ?? "";
        if (!id) return;
        const chipRect = chip.getBoundingClientRect();
        if (kind === "comment") {
          hoveredWriterCommentId = null;
          const span = el.querySelector(
            `.twyne-comment-mark[data-comment-id="${CSS.escape(id)}"]`,
          ) as HTMLElement | null;
          if (span) openUserCommentPopover(id, span);
        } else if (kind === "suggestion") {
          const span = el.querySelector(
            `.twyne-suggestion[data-suggestion-id="${CSS.escape(id)}"]`,
          ) as HTMLElement | null;
          if (span) openSuggestionPopover(span, chip);
        } else if (kind === "note") {
          const span = el.querySelector(
            `.twyne-persona-note[data-persona-note-id="${CSS.escape(id)}"]`,
          ) as HTMLElement | null;
          if (span) {
            const pop = buildNotePopoverFromRect(
              chipRect,
              readPersonaNoteAttrs(span),
              true,
            );
            store.notePopover = pop;
            requestThreadFor(pop.id);
          }
        }
        return;
      }

      // Plain click on a marked span — defer to ProseMirror for
      // caret placement. Only act to close stray cards (click-away).
      if (!target.closest(".persona-note-card")) {
        const inNote = !!target.closest(".twyne-persona-note");
        if (!inNote) store.notePopover = null;
      }
      if (
        !target.closest(".twyne-suggestion") &&
        !target.closest(".suggestion-card")
      ) {
        store.suggestionPopover = null;
      }
      if (
        !target.closest(".twyne-comment-mark") &&
        !target.closest(".user-comment-card")
      ) {
        store.userCommentPopover = null;
      }
    });

    // ── Double-click on a comment mark: dismiss the popover and drop
    // the caret into the marked passage. Now a safety net since the
    // single-click path no longer opens the popover for marked text. ──
    el.addEventListener("dblclick", (e) => {
      const target = e.target as HTMLElement;
      const commentMark = target.closest(
        ".twyne-comment-mark",
      ) as HTMLElement | null;
      if (!commentMark) return;
      store.userCommentPopover = null;
      const pos = editor.view.posAtDOM(commentMark, 0);
      if (typeof pos === "number" && pos >= 0) {
        editor.commands.focus(pos);
      } else {
        editor.commands.focus();
      }
    });

    // ── Typing suppression: disarm hover, close no-thread previews ──
    // We listen on the editor element rather than
    // `editor.on("transaction")` so that remote multiplayer
    // transactions don't disarm hover based on *someone else's*
    // keystrokes.
    el.addEventListener("keydown", (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const k = e.key;
      const isPrintable = k.length === 1;
      if (
        !isPrintable &&
        k !== "Backspace" &&
        k !== "Delete" &&
        k !== "Enter"
      ) {
        return;
      }
      hoverArmed = false;
      clearHoverTimer();
      // An unpinned preview (no thread, not replying) closes — but a
      // pinned card or one that's mid-thread stays open so the
      // conversation can continue.
      const p = store.notePopover;
      if (p && !p.pinned && !p.replying && p.thread.length === 0) {
        store.notePopover = null;
      }
    });
    // Re-arm hover only on real mouse motion (not synthetic scroll
    // mousemove events). Listener on `document` so moving out of the
    // editor area still re-arms.
    const rearmOnMove = (e: MouseEvent) => {
      const dx = e.clientX - lastMouse.x;
      const dy = e.clientY - lastMouse.y;
      lastMouse = { x: e.clientX, y: e.clientY };
      if (Math.hypot(dx, dy) > 3) {
        hoverArmed = true;
      }
    };
    document.addEventListener("mousemove", rearmOnMove);

    // ── Global Escape: close any of the three popovers ──
    // Listens on `window` so it works even when focus is in the
    // reply textarea.
    const onGlobalKeydown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const editingField =
        !!target &&
        (target.matches("input, textarea, select") ||
          (target.isContentEditable && !target.closest(".ProseMirror")));
      const key = e.key.toLowerCase();

      if (!editingField) {
        const matched = EDITOR_KEYBINDINGS.find((binding) =>
          chordMatches(
            {
              key,
              metaKey: e.metaKey,
              ctrlKey: e.ctrlKey,
              altKey: e.altKey,
              shiftKey: e.shiftKey,
            },
            binding.shortcut,
          ),
        );
        if (matched) {
          e.preventDefault();
          void runRegistryCommand(matched.commandId);
          return;
        }
      }
      if (e.key !== "Escape") return;
      if (store.notePopover) store.notePopover = null;
      if (store.userCommentPopover) store.userCommentPopover = null;
      if (store.suggestionPopover) store.suggestionPopover = null;
      if (store.openPicker) store.openPicker = null;
      store.showFindReplace = false;
      store.showOutline = false;
    };
    window.addEventListener("keydown", onGlobalKeydown);

    store.editor = editor;
    const tableToolbarController = createTableToolbarController(
      editor,
      (snapshot, cellFormat) => {
        store.tableToolbar = snapshot;
        store.cellFormat = cellFormat;
      },
    );

    // ── Vertical (row-height) resize on the header row ──
    // Tiptap's Table extension only ships a column-resize handle
    // (the 3px vertical strip on the right edge of each cell).
    // Header rows are tall by default and the writer often wants
    // them shorter — so we attach a thin horizontal grip along
    // the bottom of each <th> in the first row and translate
    try {
      await client.mutation(api.sync.updateSuggestionStatus, {
        folioId: store.activeFolioId,
        suggestionId: pop.id,
        status: "rejected",
      });
    } catch {
      /* sync will retry */
    }
  }
  store.suggestionPopover = null;
});

/**
 * Open the user-comment popover for a given mark. Loads the body,
 * replies, and resolve state from Lix (Convex will catch up on
 * the next sync). The popover position is anchored to the mark's
 * bounding rect, with a small offset to keep it readable.
 */
const openUserCommentPopover = $(
  async (commentId: string, markEl: HTMLElement) => {
    const rect = markEl.getBoundingClientRect();
    const pageRect = markEl
      .closest<HTMLElement>(".page-canvas")
      ?.getBoundingClientRect();
    const geom = computeMarginCardGeometry({
      vw: window.innerWidth,
      vh: window.innerHeight,
      rect: {
        left: rect.left,
        top: rect.top,
        bottom: rect.bottom,
      },
      page: pageRect
        ? { left: pageRect.left, right: pageRect.right }
        : { left: rect.left, right: rect.right },
    });
    const all = await loadUserComments();
    const c = all.find(
      (x) => x.id === commentId && x.folioId === store.activeFolioId,
    );
    if (!c) {
      // The mark exists but the body didn't sync. Show a placeholder
      // so the writer can resolve or delete it; the next addComment
      // round-trip will populate the body.
      store.userCommentPopover = {
        mode: "thread",
        visible: true,
        id: commentId,
        author: "You",
        text: "(comment body not yet synced)",
        quote: markEl.textContent ?? "",
        createdAt: Date.now(),
        x: geom.x,
        top: geom.top,
        bottom: geom.bottom,
        maxH: geom.maxH,
        from: null,
        to: null,
        resolved: false,
        replies: [],
        draft: "",
      };
      return;
    }
    store.userCommentPopover = {
      mode: "thread",
      visible: true,
      id: c.id,
      author: c.author,
      text: c.text,
      quote: c.anchor ?? markEl.textContent ?? "",
      createdAt: c.createdAt,
      x: geom.x,
      top: geom.top,
      bottom: geom.bottom,
      maxH: geom.maxH,
      from: null,
      to: null,
      resolved: c.resolved,
      replies: c.replies,
      draft: "",
    };
  },
);

const closeUserCommentPopover = $(() => {
  const popover = store.userCommentPopover;
  store.userCommentPopover =
    popover?.mode === "compose" ? { ...popover, visible: false } : null;
});

const submitUserCommentReply = $(async (commentId: string) => {
  const popover = store.userCommentPopover;
  if (!popover || popover.id !== commentId) return;
  const text = popover.draft.trim();
  if (!text) return;
  const reply: UserCommentReply = {
    id: `ucr-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    author: "You",
    authorKind: "user",
    text,
    createdAt: Date.now(),
  };
  // Local persistence
  const all = await appendUserCommentReply(commentId, reply);
  const updated = all.find((x) => x.id === commentId);
  if (updated) {
    store.userCommentPopover = {
      ...popover,
      replies: updated.replies,
      draft: "",
    };
  }
  // Cloud sync (best-effort, silent on failure)
  const client = clientSig.value;
  if (client) {
    try {
      await client.mutation(api.userComments.addReply, {
        replyId: reply.id,
        commentId,
        author: reply.author,
        text: reply.text,
      });
    } catch (err) {
      console.warn("[twyne:editor] user comment reply sync failed:", err);
    }
  }
  // Tell the Marginalia panel (and any other listener) the thread grew.
  // Without this, the right-rail view stays stale until the panel
  // remounts, which makes it look like the reply vanished.
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
  window.dispatchEvent(
    new CustomEvent("twyne:user-comment-mentions", {
      detail: { commentId, text },
    }),
  );
});

const toggleResolveUserComment = $(async (commentId: string) => {
  const all = await toggleUserCommentResolved(commentId);
  const updated = all.find((x) => x.id === commentId);
  const popover = store.userCommentPopover;
  if (popover && popover.id === commentId && updated) {
    store.userCommentPopover = { ...popover, resolved: updated.resolved };
  }
  const client = clientSig.value;
  if (client) {
    try {
      await client.mutation(api.userComments.resolveComment, { commentId });
    } catch (err) {
      console.warn("[twyne:editor] resolve sync failed:", err);
    }
  }
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
});

const deleteUserCommentLocal = $(async (commentId: string) => {
  await deleteUserComment(commentId);
  // Strike exactly this mark from the document. A second margin may quote
  // the same passage and must remain visible.
  if (store.editor) removeCommentMarkById(store.editor, commentId);
  if (store.userCommentPopover?.id === commentId) {
    store.userCommentPopover = null;
  }
  const client = clientSig.value;
  if (client) {
    try {
      await client.mutation(api.userComments.deleteComment, { commentId });
    } catch (err) {
      console.warn("[twyne:editor] delete comment sync failed:", err);
    }
  }
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
});

// Marginalia list deletion routes through the editor so the stored thread
// and its document mark cannot diverge.
// eslint-disable-next-line qwik/no-use-visible-task
useVisibleTask$(({ cleanup }) => {
  const onDeleteUserComment = (event: Event) => {
    const detail = (event as CustomEvent<{ commentId?: string }>).detail;
    if (!detail?.commentId) return;
    void deleteUserCommentLocal(detail.commentId);
  };
  const onUserCommentsChanged = () => {
    const open = store.userCommentPopover;
    if (!open || open.mode !== "thread") return;
    const openId = open.id;
    void loadUserComments().then((all) => {
      const latest = all.find((comment) => comment.id === openId);
      const current = store.userCommentPopover;
      if (!latest || !current || current.id !== openId) return;
      store.userCommentPopover = {
        ...current,
        author: latest.author,
        text: latest.text,
        quote: latest.anchor ?? current.quote,
        createdAt: latest.createdAt,
        resolved: latest.resolved,
        replies: latest.replies,
      };
    });
  };
  window.addEventListener("twyne:delete-user-comment", onDeleteUserComment);
  window.addEventListener(
    "twyne:user-comments-changed",
    onUserCommentsChanged,
  );
  cleanup(() => {
    window.removeEventListener(
      "twyne:delete-user-comment",
      onDeleteUserComment,
    );
    window.removeEventListener(
      "twyne:user-comments-changed",
      onUserCommentsChanged,
    );
  });
});

/** Fire-and-forget: persist a new comment to Lix + Convex. */
const persistNewComment = $(
  async (
    commentId: string,
    text: string,
    anchor: string,
    folioId: string,
  ) => {
    try {
      await upsertUserComment({
        id: commentId,
        folioId,
        text,
        author: "You",
        anchor,
        resolved: false,
        createdAt: Date.now(),
        updatedAt: Date.now(),
        replies: [],
      });
      const client = clientSig.value;
      if (client && folioId) {
        try {
          await client.mutation(api.userComments.addComment, {
            commentId,
            folioId,
            text,
            author: "You",
            anchor,
          });
        } catch (err) {
          console.warn("[twyne:editor] addComment sync failed:", err);
        }
      }
      // The Marginalia panel lives in a sibling component and watches
      // this event to know when to refetch. Fire it once the local
      // write is committed so the writer's new note shows up there
      // without a manual reload.
      window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
      return true;
    } catch (err) {
      console.warn("[twyne:editor] persistNewComment failed:", err);
      return false;
    }
  },
);

/** Create one anchored marginal note from a preserved text range. */
const createSelectionComment = $(
  async (
    body: string,
    range: { from: number; to: number },
    openPopover: boolean,
  ): Promise<string | null> => {
    const editor = store.editor;
    if (
      !editor ||
      range.from >= range.to ||
      range.to > editor.state.doc.content.size
    ) {
      return null;
    }
    const anchor = editor.state.doc.textBetween(range.from, range.to, " ");
    if (!anchor.trim()) return null;

    const commentId = crypto.randomUUID();
    editor
      .chain()
      .focus()
      .setTextSelection(range)
      .setMark("commentMark", {
        id: commentId,
        author: "You",
        color: "var(--color-writer-note)",
      })
      .run();

    const persisted = await persistNewComment(
      commentId,
      body,
      anchor,
      store.activeFolioId || "",
    );
    if (!persisted) return null;

    window.dispatchEvent(
      new CustomEvent("twyne:user-comment-mentions", {
        detail: { commentId, text: body },
      }),
    );

    if (openPopover) {
      requestAnimationFrame(() => {
        const markEl = document.querySelector(
          `.twyne-comment-mark[data-comment-id="${commentId}"]`,
        ) as HTMLElement | null;
        if (markEl) void openUserCommentPopover(commentId, markEl);
      });
    }
    return commentId;
  },
);

/** Open the writer's note beside the selected passage without filing it. */
const openWriterMarginComposer = $(
  (range: { from: number; to: number }) => {
    const editor = store.editor;
    if (!editor || range.from >= range.to) return;
    const quote = editor.state.doc.textBetween(range.from, range.to, " ");
    if (!quote.trim()) return;

    const start = editor.view.coordsAtPos(range.from);
    const end = editor.view.coordsAtPos(range.to);
    const pageRect = editor.view.dom
      .closest<HTMLElement>(".page-canvas")
      ?.getBoundingClientRect();
    const geom = computeMarginCardGeometry({
      vw: window.innerWidth,
      vh: window.innerHeight,
      rect: {
        left: Math.min(start.left, end.left),
        top: Math.min(start.top, end.top),
        bottom: Math.max(start.bottom, end.bottom),
      },
      page: pageRect
        ? { left: pageRect.left, right: pageRect.right }
        : {
            left: Math.min(start.left, end.left),
            right: Math.max(start.right, end.right),
          },
      idealH: 360,
    });
    const prior = store.userCommentPopover;
    const restoreDraft =
      prior?.mode === "compose" &&
      prior.from === range.from &&
      prior.to === range.to
        ? prior.draft
        : "";
    store.userCommentPopover = {
      mode: "compose",
      visible: true,
      id: "draft-margin",
      author: "You",
      text: "",
      quote,
      createdAt: Date.now(),
      x: geom.x,
      top: geom.top,
      bottom: geom.bottom,
      maxH: geom.maxH,
      from: range.from,
      to: range.to,
      resolved: false,
      replies: [],
      draft: restoreDraft,
    };
    store.selectionAction = null;
  },
);

const submitWriterMargin = $(async () => {
  const popover = store.userCommentPopover;
  if (
    !popover ||
    popover.mode !== "compose" ||
    popover.from == null ||
    popover.to == null ||
    !popover.draft.trim()
  ) {
    return;
  }
  await createSelectionComment(
    popover.draft.trim(),
    { from: popover.from, to: popover.to },
    true,
  );
});

const discardWriterMargin = $(() => {
  if (store.userCommentPopover?.mode === "compose") {
    store.userCommentPopover = null;
  }
});

const handleDragOver = $(() => {
  store.isDragOver = true;
});

const handleDragLeave = $(() => {
  store.isDragOver = false;
});

const handleDrop = $(() => {
  store.isDragOver = false;
});

const insertImage = $((src: string, alt?: string) => {
  store.editor
    ?.chain()
    .focus()
    .insertContent({
      type: "image",
      attrs: { src, alt: alt || "", offline: src.startsWith("data:") },
    })

output.text:
          getTailElement: () =>
            document.querySelector<HTMLElement>(".manuscript-notes"),
          onPaginate: (info: PaginationInfo) => {
            store.pageCount = info.pageCount;
            store.paginationActive = info.active;
          },
        }),
      ],
      content: initialContent,
      editorProps: {
        attributes: {
          class: "ProseMirror",
        },
        handleDrop: (view, event, _slice, moved) => {
          if (moved) return false;
          const coords = { left: event.clientX, top: event.clientY };
          const pos = view.posAtCoords(coords);
          if (!pos) return false;

          const html = event.dataTransfer?.getData("text/html");
          if (html) {
            if (html.includes("<table") || html.includes("<img")) {
              const tempDiv = document.createElement("div");
              tempDiv.innerHTML = html;
              const img = tempDiv.querySelector("img");
              if (img?.src) {
                const node = view.state.schema.nodes.image.create({
                  src: img.src,
                  alt: img.alt || "",
                });
                const tr = view.state.tr.insert(pos.pos, node);
                view.dispatch(tr);
                return true;
              }
            }
          }

          return false;
        },
      },
      onUpdate: ({ editor: e }) => {
        scheduleLiveMeta(e);
        scheduleDerive(e);
      },
    });

    // ProseMirror handles pointer events inside its own managed DOM and
    // can stop them before Qwik's delegated listener reaches the mount
    // wrapper. Capture on the actual editor surface so returning to the
    // manuscript always clears transient editorial furniture.
    const dismissEditorialFurniture = () => {
      store.showImageInput = false;
      store.selectionAction = null;
      const comment = store.userCommentPopover;
      store.userCommentPopover =
        comment?.mode === "compose" ? { ...comment, visible: false } : null;
      store.openPicker = null;
      void onManuscriptFocus$?.();
    };
    editor.view.dom.addEventListener(
      "mousedown",
      dismissEditorialFurniture,
      true,
    );
    editor.view.dom.addEventListener(
      "touchstart",
      dismissEditorialFurniture,
      true,
    );
    cleanup(() => {
      editor.view.dom.removeEventListener(
        "mousedown",
        dismissEditorialFurniture,
        true,
      );
      editor.view.dom.removeEventListener(
        "touchstart",
        dismissEditorialFurniture,
        true,
      );
    });

    // Sharing must serialize the exact document Tiptap owns, including
    // edits still inside the route's persistence debounce. The share
    // control requests this snapshot synchronously immediately before it
    // mirrors and serializes Lix.
    const provideDraftSnapshot = (event: Event) => {
      const detail = (event as CustomEvent<DraftSnapshotRequest>).detail;
      if (detail.folioId === store.activeFolioId) {
        detail.html = editor.getHTML();
      }
    };
    window.addEventListener(DRAFT_SNAPSHOT_REQUEST, provideDraftSnapshot);
    cleanup(() =>
      window.removeEventListener(
        DRAFT_SNAPSHOT_REQUEST,
        provideDraftSnapshot,
      ),
    );

    const refreshActive = () => {
      const { from, to } = editor.state.selection;
      store.hasSelection = from !== to;
      if (from !== to && editor.state.selection instanceof TextSelection) {
        const text = editor.state.doc.textBetween(from, to, " ").trim();
        if (text) {
          const start = editor.view.coordsAtPos(from);
          const end = editor.view.coordsAtPos(to);
          const cardHalfWidth = Math.min(240, window.innerWidth / 2 - 8);
          const center =
            (Math.min(start.left, end.left) +
              Math.max(start.right, end.right)) /
            2;
          const x = Math.max(
            cardHalfWidth,
            Math.min(window.innerWidth - cardHalfWidth, center),
          );
          const placement = start.top > 112 ? "above" : "below";
          const prior = store.selectionAction;
          store.selectionAction = {
            from,
            to,
            text,
            x,
            y: placement === "above" ? start.top - 10 : end.bottom + 10,
            placement,
            error:
              prior?.from === from && prior.to === to ? prior.error : null,
          };
        } else {
          store.selectionAction = null;
        }
      } else {
        store.selectionAction = null;
      }
      store.active = {
        bold: editor.isActive("bold"),
        italic: editor.isActive("italic"),
        underline: editor.isActive("underline"),
        strike: editor.isActive("strike"),
        highlight: editor.isActive("highlight"),
        h1: editor.isActive("heading", { level: 1 }),
        h2: editor.isActive("heading", { level: 2 }),
        h3: editor.isActive("heading", { level: 3 }),
        bullet: editor.isActive("bulletList"),
        ordered: editor.isActive("orderedList"),
        taskList: editor.isActive("taskList"),
        blockquote: editor.isActive("blockquote"),
        code: editor.isActive("codeBlock"),
        left: editor.isActive({ textAlign: "left" }),
        center: editor.isActive({ textAlign: "center" }),
        right: editor.isActive({ textAlign: "right" }),
        justify: editor.isActive({ textAlign: "justify" }),
        superscript: editor.isActive("superscript"),
        subscript: editor.isActive("subscript"),
        isInTable: editor.isActive("table"),
        canMergeCells: editor.can().mergeCells(),
        canSplitCell: editor.can().splitCell(),
      };
      store.selectedImage = editor.isActive("image")
        ? (editor.getAttributes("image") as ImageNodeAttributes)
        color:
          suggestionSpan.getAttribute("data-suggestion-color") ??
          "var(--color-vermilion)",
        original: suggestionSpan.textContent ?? "",
        replacement:
          suggestionSpan.getAttribute("data-suggestion-replacement") ?? "",
        rationale:
          suggestionSpan.getAttribute("data-suggestion-rationale") ?? "",
        x: Math.max(8, Math.min(rect.left, window.innerWidth - 360)),
        y: rect.bottom + 8,
        busy: false,
      };
    };

    // ── Hover: preview a persona note below its sentence ──
    // Non-blocking rules:
    //   1. Hover-intent delay (350ms) — passing through doesn't
    //      accidentally open a card.
    //   2. Typing disarm — once the writer types (or deletes /
    //      hits Enter), the next hover is suppressed. We re-arm
    //      only on real mouse motion (>3px), filtering the
    //      synthetic mousemove that scroll-under-cursor fires.
    //   3. Pinned / replying / has-thread cards never close from
    //      mouseout alone.
    let hoverTimer: ReturnType<typeof setTimeout> | null = null;
    let hoverArmed = true;
    let hoveredWriterCommentId: string | null = null;
    let lastMouse = { x: 0, y: 0 };
    const clearHoverTimer = () => {
      if (hoverTimer) {
        clearTimeout(hoverTimer);
        hoverTimer = null;
      }
    };
    el.addEventListener("mouseover", (e) => {
      const target = e.target as HTMLElement;
      const noteSpan = target.closest(
        ".twyne-persona-note",
      ) as HTMLElement | null;
      const writerCommentSpan = target.closest(
        ".twyne-comment-mark",
      ) as HTMLElement | null;
      const chip = target.closest(
        ".twyne-mark-anchor",
      ) as HTMLElement | null;
      if (!noteSpan && !writerCommentSpan && !chip) return;
      if (writerCommentSpan) {
        if (store.userCommentPopover?.visible) return;
        if (!hoverArmed) return;
        const commentId =
          writerCommentSpan.getAttribute("data-comment-id") ?? "";
        if (!commentId) return;
        clearHoverTimer();
        hoverTimer = setTimeout(() => {
          hoveredWriterCommentId = commentId;
          void openUserCommentPopover(commentId, writerCommentSpan);
        }, 350);
        return;
      }
      // Don't clobber a pinned card the writer is interacting with.
      if (store.notePopover?.pinned) return;
      if (!hoverArmed) return;
      // Resolve to the actual note span for geometry. The chip
      // belongs to whichever note span it sits in (or directly
      // adjacent to).
      const anchor =
        noteSpan ??
        (chip?.closest(".twyne-persona-note") as HTMLElement | null);
      if (!anchor) return;
      clearHoverTimer();
      hoverTimer = setTimeout(() => {
        buildAndPin(anchor, false);
      }, 350);
    });
    el.addEventListener("mouseout", (e) => {
      const related = (e as MouseEvent).relatedTarget as HTMLElement | null;
      // Stay open while moving onto the card, the marked span, or
      // its corresponding anchor chip (text → chip → card).
      if (related?.closest(".manuscript-comment-card")) return;
      if (related?.closest(".twyne-persona-note")) return;
      if (related?.closest(".twyne-comment-mark")) return;
      if (related?.closest(".twyne-mark-anchor")) return;
      // Even when we don't close, cancel any pending hover-open
      // timer so a fast pass-through doesn't surprise the writer.
      clearHoverTimer();
      if (hoveredWriterCommentId) {
        if (
          store.userCommentPopover?.id === hoveredWriterCommentId &&
          !store.userCommentPopover.draft.trim()
        ) {
          store.userCommentPopover = null;
        }
        hoveredWriterCommentId = null;
        return;
      }
      // Mid-conversation: keep the live thread open even if the
      // popover was opened by hover rather than a click.
      if (store.notePopover?.pinned) return;
      if (store.notePopover?.replying) return;
      if ((store.notePopover?.thread.length ?? 0) > 0) return;
      store.notePopover = null;
    });

    // ── Click handler: anchor-chip routes by data-anchor-kind; mark
    // clicks fall through to ProseMirror (caret placement, no popover). ──
    el.addEventListener("click", (e) => {
      dismissEditorialFurniture();
      const target = e.target as HTMLElement;

      // Anchor chip first — must preventDefault so clicking the
      // chip doesn't also place the caret.
      const chip = target.closest(
        ".twyne-mark-anchor",
      ) as HTMLElement | null;
      if (chip) {
        e.preventDefault();
        const kind = chip.getAttribute("data-anchor-kind");
        const id = chip.getAttribute("data-anchor-id") ?? "";
        if (!id) return;
        const chipRect = chip.getBoundingClientRect();
        if (kind === "comment") {
          hoveredWriterCommentId = null;
          const span = el.querySelector(
            `.twyne-comment-mark[data-comment-id="${CSS.escape(id)}"]`,
          ) as HTMLElement | null;
          if (span) openUserCommentPopover(id, span);
        } else if (kind === "suggestion") {
          const span = el.querySelector(
            `.twyne-suggestion[data-suggestion-id="${CSS.escape(id)}"]`,
          ) as HTMLElement | null;
          if (span) openSuggestionPopover(span, chip);
        } else if (kind === "note") {
          const span = el.querySelector(
            `.twyne-persona-note[data-persona-note-id="${CSS.escape(id)}"]`,
          ) as HTMLElement | null;
          if (span) {
            const pop = buildNotePopoverFromRect(
              chipRect,
              readPersonaNoteAttrs(span),
              true,
            );
            store.notePopover = pop;
            requestThreadFor(pop.id);
          }
        }
        return;
      }

      // Plain click on a marked span — defer to ProseMirror for
      // caret placement. Only act to close stray cards (click-away).
      if (!target.closest(".persona-note-card")) {
        const inNote = !!target.closest(".twyne-persona-note");
        if (!inNote) store.notePopover = null;
      }
      if (
        !target.closest(".twyne-suggestion") &&
        !target.closest(".suggestion-card")
      ) {
        store.suggestionPopover = null;
      }
      if (
        !target.closest(".twyne-comment-mark") &&
        !target.closest(".user-comment-card")
      ) {
        store.userCommentPopover = null;
      }
    });

    // ── Double-click on a comment mark: dismiss the popover and drop
    // the caret into the marked passage. Now a safety net since the
    // single-click path no longer opens the popover for marked text. ──
    el.addEventListener("dblclick", (e) => {
      const target = e.target as HTMLElement;
      const commentMark = target.closest(
        ".twyne-comment-mark",
      ) as HTMLElement | null;
      if (!commentMark) return;
      store.userCommentPopover = null;
      const pos = editor.view.posAtDOM(commentMark, 0);
      if (typeof pos === "number" && pos >= 0) {
        editor.commands.focus(pos);
      } else {
        editor.commands.focus();
      }
    });

    // ── Typing suppression: disarm hover, close no-thread previews ──
    // We listen on the editor element rather than
    // `editor.on("transaction")` so that remote multiplayer
    // transactions don't disarm hover based on *someone else's*
    // keystrokes.
    el.addEventListener("keydown", (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const k = e.key;
      const isPrintable = k.length === 1;
      if (
        !isPrintable &&
        k !== "Backspace" &&
        k !== "Delete" &&
        k !== "Enter"
      ) {
        return;
      }
      hoverArmed = false;
      clearHoverTimer();
      // An unpinned preview (no thread, not replying) closes — but a
      // pinned card or one that's mid-thread stays open so the
      // conversation can continue.
      const p = store.notePopover;
      if (p && !p.pinned && !p.replying && p.thread.length === 0) {
        store.notePopover = null;
      }
    });
    // Re-arm hover only on real mouse motion (not synthetic scroll
    // mousemove events). Listener on `document` so moving out of the
    // editor area still re-arms.
    const rearmOnMove = (e: MouseEvent) => {
      const dx = e.clientX - lastMouse.x;
      const dy = e.clientY - lastMouse.y;
      lastMouse = { x: e.clientX, y: e.clientY };
      if (Math.hypot(dx, dy) > 3) {
        hoverArmed = true;
      }
    };
    document.addEventListener("mousemove", rearmOnMove);

    // ── Global Escape: close any of the three popovers ──
    // Listens on `window` so it works even when focus is in the
    // reply textarea.
    const onGlobalKeydown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const editingField =
        !!target &&
        (target.matches("input, textarea, select") ||
          (target.isContentEditable && !target.closest(".ProseMirror")));
      const key = e.key.toLowerCase();

      if (!editingField) {
        const matched = EDITOR_KEYBINDINGS.find((binding) =>
          chordMatches(
            {
              key,
              metaKey: e.metaKey,
              ctrlKey: e.ctrlKey,
              altKey: e.altKey,
              shiftKey: e.shiftKey,
            },
            binding.shortcut,
          ),
        );
        if (matched) {
          e.preventDefault();
          void runRegistryCommand(matched.commandId);
          return;
        }
      }
      if (e.key !== "Escape") return;
      if (store.notePopover) store.notePopover = null;
      if (store.userCommentPopover) store.userCommentPopover = null;
      if (store.suggestionPopover) store.suggestionPopover = null;
      if (store.openPicker) store.openPicker = null;
      store.showFindReplace = false;
      store.showOutline = false;
    };
    window.addEventListener("keydown", onGlobalKeydown);

    store.editor = editor;
    const tableToolbarController = createTableToolbarController(
      editor,
      (snapshot, cellFormat) => {
        store.tableToolbar = snapshot;
        store.cellFormat = cellFormat;
      },
    );

    // ── Vertical (row-height) resize on the header row ──
    // Tiptap's Table extension only ships a column-resize handle
    // (the 3px vertical strip on the right edge of each cell).
    // Header rows are tall by default and the writer often wants
    // them shorter — so we attach a thin horizontal grip along
    // the bottom of each <th> in the first row and translate
    try {
      await client.mutation(api.sync.updateSuggestionStatus, {
        folioId: store.activeFolioId,
        suggestionId: pop.id,
        status: "rejected",
      });
    } catch {
      /* sync will retry */
    }
  }
  store.suggestionPopover = null;
});

/**
 * Open the user-comment popover for a given mark. Loads the body,
 * replies, and resolve state from Lix (Convex will catch up on
 * the next sync). The popover position is anchored to the mark's
 * bounding rect, with a small offset to keep it readable.
 */
const openUserCommentPopover = $(
  async (commentId: string, markEl: HTMLElement) => {
    const rect = markEl.getBoundingClientRect();
    const pageRect = markEl
      .closest<HTMLElement>(".page-canvas")
      ?.getBoundingClientRect();
    const geom = computeMarginCardGeometry({
      vw: window.innerWidth,
      vh: window.innerHeight,
      rect: {
        left: rect.left,
        top: rect.top,
        bottom: rect.bottom,
      },
      page: pageRect
        ? { left: pageRect.left, right: pageRect.right }
        : { left: rect.left, right: rect.right },
    });
    const all = await loadUserComments();
    const c = all.find(
      (x) => x.id === commentId && x.folioId === store.activeFolioId,
    );
    if (!c) {
      // The mark exists but the body didn't sync. Show a placeholder
      // so the writer can resolve or delete it; the next addComment
      // round-trip will populate the body.
      store.userCommentPopover = {
        mode: "thread",
        visible: true,
        id: commentId,
        author: "You",
        text: "(comment body not yet synced)",
        quote: markEl.textContent ?? "",
        createdAt: Date.now(),
        x: geom.x,
        top: geom.top,
        bottom: geom.bottom,
        maxH: geom.maxH,
        from: null,
        to: null,
        resolved: false,
        replies: [],
        draft: "",
      };
      return;
    }
    store.userCommentPopover = {
      mode: "thread",
      visible: true,
      id: c.id,
      author: c.author,
      text: c.text,
      quote: c.anchor ?? markEl.textContent ?? "",
      createdAt: c.createdAt,
      x: geom.x,
      top: geom.top,
      bottom: geom.bottom,
      maxH: geom.maxH,
      from: null,
      to: null,
      resolved: c.resolved,
      replies: c.replies,
      draft: "",
    };
  },
);

const closeUserCommentPopover = $(() => {
  const popover = store.userCommentPopover;
  store.userCommentPopover =
    popover?.mode === "compose" ? { ...popover, visible: false } : null;
});

const submitUserCommentReply = $(async (commentId: string) => {
  const popover = store.userCommentPopover;
  if (!popover || popover.id !== commentId) return;
  const text = popover.draft.trim();
  if (!text) return;
  const reply: UserCommentReply = {
    id: `ucr-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    author: "You",
    authorKind: "user",
    text,
    createdAt: Date.now(),
  };
  // Local persistence
  const all = await appendUserCommentReply(commentId, reply);
  const updated = all.find((x) => x.id === commentId);
  if (updated) {
    store.userCommentPopover = {
      ...popover,
      replies: updated.replies,
      draft: "",
    };
  }
  // Cloud sync (best-effort, silent on failure)
  const client = clientSig.value;
  if (client) {
    try {
      await client.mutation(api.userComments.addReply, {
        replyId: reply.id,
        commentId,
        author: reply.author,
        text: reply.text,
      });
    } catch (err) {
      console.warn("[twyne:editor] user comment reply sync failed:", err);
    }
  }
  // Tell the Marginalia panel (and any other listener) the thread grew.
  // Without this, the right-rail view stays stale until the panel
  // remounts, which makes it look like the reply vanished.
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
  window.dispatchEvent(
    new CustomEvent("twyne:user-comment-mentions", {
      detail: { commentId, text },
    }),
  );
});

const toggleResolveUserComment = $(async (commentId: string) => {
  const all = await toggleUserCommentResolved(commentId);
  const updated = all.find((x) => x.id === commentId);
  const popover = store.userCommentPopover;
  if (popover && popover.id === commentId && updated) {
    store.userCommentPopover = { ...popover, resolved: updated.resolved };
  }
  const client = clientSig.value;
  if (client) {
    try {
      await client.mutation(api.userComments.resolveComment, { commentId });
    } catch (err) {
      console.warn("[twyne:editor] resolve sync failed:", err);
    }
  }
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
});

const deleteUserCommentLocal = $(async (commentId: string) => {
  await deleteUserComment(commentId);
  // Strike exactly this mark from the document. A second margin may quote
  // the same passage and must remain visible.
  if (store.editor) removeCommentMarkById(store.editor, commentId);
  if (store.userCommentPopover?.id === commentId) {
    store.userCommentPopover = null;
  }
  const client = clientSig.value;
  if (client) {
    try {
      await client.mutation(api.userComments.deleteComment, { commentId });
    } catch (err) {
      console.warn("[twyne:editor] delete comment sync failed:", err);
    }
  }
  window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
});

// Marginalia list deletion routes through the editor so the stored thread
// and its document mark cannot diverge.
// eslint-disable-next-line qwik/no-use-visible-task
useVisibleTask$(({ cleanup }) => {
  const onDeleteUserComment = (event: Event) => {
    const detail = (event as CustomEvent<{ commentId?: string }>).detail;
    if (!detail?.commentId) return;
    void deleteUserCommentLocal(detail.commentId);
  };
  const onUserCommentsChanged = () => {
    const open = store.userCommentPopover;
    if (!open || open.mode !== "thread") return;
    const openId = open.id;
    void loadUserComments().then((all) => {
      const latest = all.find((comment) => comment.id === openId);
      const current = store.userCommentPopover;
      if (!latest || !current || current.id !== openId) return;
      store.userCommentPopover = {
        ...current,
        author: latest.author,
        text: latest.text,
        quote: latest.anchor ?? current.quote,
        createdAt: latest.createdAt,
        resolved: latest.resolved,
        replies: latest.replies,
      };
    });
  };
  window.addEventListener("twyne:delete-user-comment", onDeleteUserComment);
  window.addEventListener(
    "twyne:user-comments-changed",
    onUserCommentsChanged,
  );
  cleanup(() => {
    window.removeEventListener(
      "twyne:delete-user-comment",
      onDeleteUserComment,
    );
    window.removeEventListener(
      "twyne:user-comments-changed",
      onUserCommentsChanged,
    );
  });
});

/** Fire-and-forget: persist a new comment to Lix + Convex. */
const persistNewComment = $(
  async (
    commentId: string,
    text: string,
    anchor: string,
    folioId: string,
  ) => {
    try {
      await upsertUserComment({
        id: commentId,
        folioId,
        text,
        author: "You",
        anchor,
        resolved: false,
        createdAt: Date.now(),
        updatedAt: Date.now(),
        replies: [],
      });
      const client = clientSig.value;
      if (client && folioId) {
        try {
          await client.mutation(api.userComments.addComment, {
            commentId,
            folioId,
            text,
            author: "You",
            anchor,
          });
        } catch (err) {
          console.warn("[twyne:editor] addComment sync failed:", err);
        }
      }
      // The Marginalia panel lives in a sibling component and watches
      // this event to know when to refetch. Fire it once the local
      // write is committed so the writer's new note shows up there
      // without a manual reload.
      window.dispatchEvent(new CustomEvent("twyne:user-comments-changed"));
      return true;
    } catch (err) {
      console.warn("[twyne:editor] persistNewComment failed:", err);
      return false;
    }
  },
);

/** Create one anchored marginal note from a preserved text range. */
const createSelectionComment = $(
  async (
    body: string,
    range: { from: number; to: number },
    openPopover: boolean,
  ): Promise<string | null> => {
    const editor = store.editor;
    if (
      !editor ||
      range.from >= range.to ||
      range.to > editor.state.doc.content.size
    ) {
      return null;
    }
    const anchor = editor.state.doc.textBetween(range.from, range.to, " ");
    if (!anchor.trim()) return null;

    const commentId = crypto.randomUUID();
    editor
      .chain()
      .focus()
      .setTextSelection(range)
      .setMark("commentMark", {
        id: commentId,
        author: "You",
        color: "var(--color-writer-note)",
      })
      .run();

    const persisted = await persistNewComment(
      commentId,
      body,
      anchor,
      store.activeFolioId || "",
    );
    if (!persisted) return null;

    window.dispatchEvent(
      new CustomEvent("twyne:user-comment-mentions", {
        detail: { commentId, text: body },
      }),
    );

    if (openPopover) {
      requestAnimationFrame(() => {
        const markEl = document.querySelector(
          `.twyne-comment-mark[data-comment-id="${commentId}"]`,
        ) as HTMLElement | null;
        if (markEl) void openUserCommentPopover(commentId, markEl);
      });
    }
    return commentId;
  },
);

/** Open the writer's note beside the selected passage without filing it. */
const openWriterMarginComposer = $(
  (range: { from: number; to: number }) => {
    const editor = store.editor;
    if (!editor || range.from >= range.to) return;
    const quote = editor.state.doc.textBetween(range.from, range.to, " ");
    if (!quote.trim()) return;

    const start = editor.view.coordsAtPos(range.from);
    const end = editor.view.coordsAtPos(range.to);
    const pageRect = editor.view.dom
      .closest<HTMLElement>(".page-canvas")
      ?.getBoundingClientRect();
    const geom = computeMarginCardGeometry({
      vw: window.innerWidth,
      vh: window.innerHeight,
      rect: {
        left: Math.min(start.left, end.left),
        top: Math.min(start.top, end.top),
        bottom: Math.max(start.bottom, end.bottom),
      },
      page: pageRect
        ? { left: pageRect.left, right: pageRect.right }
        : {
            left: Math.min(start.left, end.left),
            right: Math.max(start.right, end.right),
          },
      idealH: 360,
    });
    const prior = store.userCommentPopover;
    const restoreDraft =
      prior?.mode === "compose" &&
      prior.from === range.from &&
      prior.to === range.to
        ? prior.draft
        : "";
    store.userCommentPopover = {
      mode: "compose",
      visible: true,
      id: "draft-margin",
      author: "You",
      text: "",
      quote,
      createdAt: Date.now(),
      x: geom.x,
      top: geom.top,
      bottom: geom.bottom,
      maxH: geom.maxH,
      from: range.from,
      to: range.to,
      resolved: false,
      replies: [],
      draft: restoreDraft,
    };
    store.selectionAction = null;
  },
);

const submitWriterMargin = $(async () => {
  const popover = store.userCommentPopover;
  if (
    !popover ||
    popover.mode !== "compose" ||
    popover.from == null ||
    popover.to == null ||
    !popover.draft.trim()
  ) {
    return;
