import { describe, expect, test } from "bun:test";
import { exportHtml, exportPlainText, stripHtml } from "./exchange";
import { DEFAULT_LAYOUT, type LayoutSettings } from "../types";
import type { ExportPayload } from "./exchange";

/**
 * The print stylesheet is the only place where the writer's page settings
 * become a physical sheet, and it had two long-standing faults: margins were
 * applied twice, and the page-number rule was a Paged Media feature Chrome
 * has never implemented. Both are guarded here so they cannot come back.
 */

function payload(overrides: Partial<ExportPayload> = {}): ExportPayload {
  return {
    title: "Specimen",
    html: "<p>Body text.</p>",
    meta: {
      title: "Specimen",
      wordCount: 2,
      characterCount: 10,
      readingTime: 1,
    },
    marginalia: [],
    ...overrides,
  } as ExportPayload;
}

const layout = (over: Partial<LayoutSettings> = {}): LayoutSettings => ({
  ...DEFAULT_LAYOUT,
  ...over,
});

describe("print stylesheet", () => {
  test("loads every font family the formatting menu can write", () => {
    const html = exportHtml(payload());
    for (const family of ["DM+Sans", "Fraunces", "Lora", "Special+Elite"]) {
      expect(html).toContain(family);
    }
  });

  test("the sheet size comes from paper and orientation", () => {
    const html = exportHtml(
      payload({ layout: layout({ paper: "a4", orientation: "landscape" }) }),
    );
    expect(html).toContain("@page { size: A4 landscape;");
  });

  test("Letter portrait is emitted for a default layout", () => {
    const html = exportHtml(payload({ layout: layout() }));
    expect(html).toContain("size: letter portrait");
  });

  test("the dead @bottom-center rule is gone", () => {
    // It never rendered — Chrome implements neither the margin-box selector
    // nor counter(page) outside one — and its presence made the exporter
    // look like it produced page numbers when it never had.
    const html = exportHtml(payload({ layout: layout({ pageNumbers: true }) }));
    expect(html).not.toContain("@bottom-center");
    // The rule, not the word — the stylesheet comments explain why it is
    // absent, and that explanation is worth keeping.
    expect(html).not.toMatch(/content:\s*counter\(page\)/);
  });

  test("body carries no margin, so page margins cannot double", () => {
    // @page owns the margins. Setting them on body as well stacked the two
    // and quietly doubled every printed margin.
    const html = exportHtml(payload({ layout: layout({ marginLeft: 3 }) }));
    expect(html).toMatch(/body\s*\{[^}]*margin:\s*0;/);
    expect(html).toMatch(/body\s*\{[^}]*padding:\s*0;/);
  });

  test("margins are converted to inches through the fixed 96px/in", () => {
    // 3rem at the pinned 16px root is 48px, which is half an inch.
    const html = exportHtml(
      payload({
        layout: layout({
          marginLeft: 3,
          marginRight: 3,
          marginTop: 3,
          marginBottom: 3,
        }),
      }),
    );
    expect(html).toContain("margin: 0.500in 0.500in 0.500in 0.500in");
  });

  test("the root font size is pinned so that conversion is exact", () => {
    const html = exportHtml(payload());
    expect(html).toMatch(/html\s*\{\s*font-size:\s*16px;\s*\}/);
  });

  test("the atomic-block contract is mirrored for the printer", () => {
    const html = exportHtml(payload());
    expect(html).toContain("break-inside: avoid");
    expect(html).toContain("break-after: avoid");
    expect(html).toContain("orphans: 2");
  });

  test("justification and hyphenation match the editor", () => {
    // The screen sets both; an export that sets neither breaks its lines
    // somewhere else and every page drifts.
    const html = exportHtml(payload());
    expect(html).toContain("text-align: justify");
    expect(html).toContain("hyphens: auto");
  });

  test("a manual page break maps to break-after: page", () => {
    const html = exportHtml(payload());
    expect(html).toMatch(/\[data-page-break\][^{]*\{[^}]*break-after:\s*page/);
  });

  test("continuous mode leaves the sheet size to the print dialog", () => {
    const html = exportHtml(
      payload({ layout: layout({ pagination: "continuous" }) }),
    );
    expect(html).toContain("size: auto");
  });

  test("portable tables, images, and math keep their export styling hooks", () => {
    const html = exportHtml(
      payload({
        html:
          '<table data-table-style="banded-rows"><caption>Results</caption><tbody><tr><td style="background-color: #ffeeaa">1</td></tr></tbody></table>' +
          '<figure data-type="image" data-image-width="50"><img src="/plate.png" alt="Plate"><figcaption>Figure one</figcaption></figure>' +
          '<span data-type="inline-math" data-math-display="inline" data-latex="x^2">x^2</span>',
      }),
    );
    expect(html).toContain('table[data-table-style="banded-rows"]');
    expect(html).toContain("background-color: #ffeeaa");
    expect(html).toContain('figure[data-type="image"] figcaption');
    expect(html).toContain('[data-math-display="inline"]');
    expect(html).toContain('data-latex="x^2"');
  });
});

describe("plain text", () => {
  test("a page break becomes a form feed", () => {
    const text = stripHtml(
      '<p>One</p><div data-type="page-break" data-page-break="true"></div><p>Two</p>',
    );
    expect(text).toContain("\f");
  });

  test("the break does not silently vanish from a text export", () => {
    const text = exportPlainText(
      payload({
        html: '<p>One</p><div data-page-break="true"></div><p>Two</p>',
      }),
    );
    expect(text).toContain("\f");
}

/* ── Endnote / footnote extraction ─────────────────────────────── */

/**
 * Regex to find inline note nodes (endnotes and footnotes) in the
 * editor HTML. The lookahead keeps it independent of attribute order —
 * TipTap serializes `data-endnote-text` before `data-type`.
 */
const NOTE_SUP_RE =
  /<sup\b(?=[^>]*data-type="(?:endnote|footnote)")[^>]*>[\s\S]*?<\/sup>/gi;

export interface InlineNote {
  kind: "endnote" | "footnote";
  text: string;
}

/**
 * Extract inline notes from `<sup data-type="endnote|footnote">` nodes
 * in the editor HTML, returning them in document order.
 */
export function extractInlineNotes(html: string): InlineNote[] {
  const notes: InlineNote[] = [];
  let m: RegExpExecArray | null;
  NOTE_SUP_RE.lastIndex = 0;
  while ((m = NOTE_SUP_RE.exec(html)) !== null) {
    const tag = m[0];
    const kind = /data-type="footnote"/i.test(tag) ? "footnote" : "endnote";
    const text = /data-endnote-text="([^"]*)"/i.exec(tag)?.[1] ?? "";
    notes.push({ kind, text: htmlDecode(text) });
  }
  return notes;
}

/** Extract endnote texts only (kept for callers that predate footnotes). */
export function extractEndnotes(html: string): string[] {
  return extractInlineNotes(html)
    .filter((n) => n.kind === "endnote")
    .map((n) => n.text);
}

/**
 * Replace note `<sup>` nodes in the HTML with numbered superscript
 * references (¹ ² ³ …) so the exported body reads naturally. Endnotes
 * and footnotes number independently, matching their export sections.
 */
function replaceNotesWithSuperscripts(html: string): string {
  let endnoteCount = 0;
  let footnoteCount = 0;
  return html.replace(NOTE_SUP_RE, (tag) => {
    if (/data-type="footnote"/i.test(tag)) {
      footnoteCount++;
      return `<sup class="footnote-ref">${toSuperscript(footnoteCount)}</sup>`;
    }
    endnoteCount++;
    return `<sup class="endnote-ref">${toSuperscript(endnoteCount)}</sup>`;
  });
}

/** Convert a number to Unicode superscript digits. */
function toSuperscript(n: number): string {
  const map: Record<string, string> = {
    "0": "\u2070",
    "1": "\u00b9",
    "2": "\u00b2",
    "3": "\u00b3",
    "4": "\u2074",
    "5": "\u2075",
    "6": "\u2076",
    "7": "\u2077",
    "8": "\u2078",
    "9": "\u2079",
  };
  return String(n)
    .split("")
    .map((d) => map[d] ?? d)
    .join("");
}

/**
 * Strip editor-only marks (persona notes, suggestions, comments) from
 * the HTML so the exported manuscript is clean prose. Endnote `<sup>`
 * nodes are preserved — they are handled separately.
 */
function stripEditorMarks(html: string): string {
  return (
    html
      // Remove persona-note spans but keep the text inside.
      .replace(
        /<span[^>]*class="twyne-persona-note"[^>]*>([\s\S]*?)<\/span>/gi,
        "$1",
      )
      // Remove suggestion spans — keep the original text (not the replacement).
      .replace(
        /<span[^>]*class="twyne-suggestion"[^>]*>([\s\S]*?)<\/span>/gi,
        "$1",
      )
      // Remove comment marks but keep text.
      .replace(
        /<span[^>]*class="twyne-comment-mark"[^>]*>([\s\S]*?)<\/span>/gi,
        "$1",
      )
  );
}

/** Build the endnotes section HTML from marginalia + inline endnotes. */
function buildEndnotesSection(
  inlineNotes: string[],
  marginalia: PersonaFeedback[],
): string {
  const entries: Array<{ source: string; text: string }> = [];

  for (const text of inlineNotes) {
    entries.push({ source: "note", text });
  }

  for (const m of marginalia) {
    const author = m.personaName || "Editor";
    const quote = m.anchor ? `"${m.anchor}" — ` : "";
    entries.push({
      source: author,
      text: `${quote}${m.feedback}`,
    });
  }

  if (entries.length === 0) return "";

  const items = entries
    .map(
      (e, i) =>
        `<li id="endnote-${i + 1}"><sup>${toSuperscript(i + 1)}</sup> ` +
        `<span class="endnote-source">${escapeHtml(e.source)}</span>: ` +
        `${escapeHtml(e.text)}</li>`,
    )
    .join("\n");

  return `<section class="endnotes">\n<h2>Notes</h2>\n<ol>\n${items}\n</ol>\n</section>\n`;
}

/**
 * Build the footnotes section HTML: inline footnotes first (matching
 * the body's numbering), then bibliography entries continuing the count.
 */
function buildFootnotesSection(
  inlineFootnotes: string[],
  bibliography: BibEntry[],
  style: CitationStyle,
): string {
  const bibEntries = bibliography.filter((b) => b.url || b.doi || b.title);
  const lines: string[] = [];

  for (const text of inlineFootnotes) {
    lines.push(escapeHtml(text));
  }
  for (const e of bibEntries) {
    lines.push(escapeHtml(formatCitation(e, style)));
  }
  if (lines.length === 0) return "";

  const items = lines
    .map(
      (body, i) =>
        `<li id="footnote-${i + 1}"><sup>${toSuperscript(i + 1)}</sup> ${body}</li>`,
    )
    .join("\n");

  return `<section class="footnotes">\n<h2>Footnotes</h2>\n<ol>\n${items}\n</ol>\n</section>\n`;
}

function htmlDecode(s: string): string {
  return s
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

